"""Publish a replayable multi-generation wheel campaign and its research twins."""
from pathlib import Path
from hashlib import sha256
import argparse,gzip,io,json,shutil,tarfile,tempfile
from . import contracts as k,campaign,selection,wheel_families,wheel_twin
ROOT=Path(__file__).resolve().parents[2]
OUTPUT=ROOT/'docs/design-engine/v06-optimisation'
FLAGS=dict(physical_accepted=False,engineering_accepted=False,configuration_adopted=False,manufacturing_release=False,operating_release=False)


def digest(path):return sha256(Path(path).read_bytes()).hexdigest()


def archive(folder,*,compact=False):
    folder=Path(folder);raw=io.BytesIO();kept={};omitted={}
    excluded={'.msh','.pre','.res','.pos','.frd','.dat','.eig','.12d','.cvg'}
    with tarfile.open(fileobj=raw,mode='w') as tar:
        for p in sorted(folder.rglob('*')):
            if p.is_symlink():raise ValueError('Ordinary artifacts required')
            if not p.is_file():continue
            name=p.relative_to(folder).as_posix();h=digest(p)
            if compact and p.suffix in excluded:omitted[name]=h;continue
            value=p.read_bytes();kept[name]=h
            item=tarfile.TarInfo(name);item.size=len(value);item.mtime=0;item.mode=0o644;tar.addfile(item,io.BytesIO(value))
        value=k.encoded(dict(schema='osr-wheel-archive-index/1',retained_sha256=kept,omitted_sha256=omitted,
            original_raw_directory=str(folder),remote_raw_storage=None,full_raw_payload_retained=not omitted,**FLAGS))
        item=tarfile.TarInfo('archive-index.json');item.size=len(value);item.mtime=0;item.mode=0o644;tar.addfile(item,io.BytesIO(value))
    value=gzip.compress(raw.getvalue(),mtime=0)
    if len(value)>64*1024**2:raise ValueError('Bounded64MiB published package required')
    return value


def _row(candidate,results):
    by={r['request']['evaluator_id']:r for r in results if r['purpose']!='confirmation'};car=wheel_families.materialize(candidate)
    motor=by['wheel-motor']['diagnostics'][0].get('native',{});body=by['wheel-body']['diagnostics'][0].get('native',{})
    return dict(candidate_id=candidate['candidate_id'],label=candidate['label'],generation=candidate['lineage'].get('generation',0),
        parents=candidate['lineage'].get('parent_candidate_ids',[]),mass_kg_per_car=car['mass']['accounted_tare_kg_per_car'],
        body_parameters=candidate['architecture']['wheel_parameters']['body'],motor_parameters=candidate['architecture']['wheel_parameters']['motor'],
        motor_required_force_N=motor.get('required_force_N'),motor_cases=[dict(speed_m_s=r['case']['speed_m_s'],execution=r['execution'],model_domain=r['model_domain'],metrics=r.get('metrics',{})) for r in motor.get('cases',[])],
        body_cases=[{key:c[key] for key in ('case','execution','maximum_vertical_displacement_m','engineering_screen','force_balance_relative_error') if key in c} for c in body.get('cases',[])],
        body_numerical_validity=body.get('numerical_validity'),body_engineering_screen=body.get('engineering_screen'),
        motor_failure_reasons=motor.get('failure_reasons'),motor_numerical_status=by['wheel-motor']['numerical_status'],
        system_metrics=by['wheel-system']['metrics'],next_tasks=by['wheel-system']['diagnostics'][0]['next_tasks'],
        integrated_journey='held',complete_installed_mass_kg=None,whole_life_cost_USD=None,**FLAGS)


def readme(summary):
    lines=['# Failure-driven v0.6 design campaign','',
        'OpenSourceRail pursues simple, affordable, locally repairable transport. This campaign connects the existing design-search coordinator to generated wheel-supported vehicle bodies, station LIMs, independent brake models, civil moving loads and research-twin exports. A failed design produces a new physical candidate; a numerical failure or missing evidence produces an explicit engineering task.','',
        '**Research selection only.** No manufacturing, operating or physical release. The [development default](../current/README.md) and [v0.5 evidence](../../archives/v0.5-maglev/README.md) remain preserved. No city performance package is regenerated.','',
        f"The bounded run completed **{summary['generations']} generations, {len(summary['candidates'])} physical candidates and {summary['primary_jobs']} primary evaluator jobs**. All generations were generated by code from the source campaign specification; the reference geometry was not manually edited between trials.",'',
        'The [retained preliminary run](preliminary-resource-failure.json.gz) completed two generations but found a real solver allocation failure. Sparse sandwich element labels made CalculiX size an integration array for over a million IDs. The numbering-only repair preserves geometry and materials, retains the 3 GiB worker limit and reruns the campaign under a new source epoch. Numerical implementation failure is not a physical design failure.','', '## Executed alternatives','',
        '| Candidate / generation | Accounted tare/car | Normal body deflection | Conditional 20 m/s motor force | Motor model status |','|---|---|---|---|']
    for r in summary['candidates']:
        body=next((c for c in r['body_cases'] if c['case']=='normal-fine'),next(iter(r['body_cases']),{}));motor=next((c for c in r['motor_cases'] if c['speed_m_s']==20),{})
        deflection='Unknown' if body.get('maximum_vertical_displacement_m') is None else f"{1000*body['maximum_vertical_displacement_m']:.2f} mm"
        force='Unknown' if motor.get('metrics',{}).get('force_N') is None else f"{motor['metrics']['force_N']/1000:.3f} kN"
        lines.append(f"| [{r['candidate_id'][:12]}](twins/{r['candidate_id']}/README.md), g{r['generation']} | {r['mass_kg_per_car']/1000:.3f} t | {deflection} | {force} | {r['motor_numerical_status']} |")
    lines += ['',
        'The body comparison includes counted floor cutouts/collars and, for the participating family, actual door/window-region sandwich stock and counted clamp/bolt connections. Balanced-skin/core/bond constants and ideal transfer are declared synthetic hypotheses. Full-integration CalculiX runs include normal/crowd loads and normal mesh refinement; necessary stiffness screens do not establish stress, buckling, local fasteners, fatigue, crash or complete flexible modes.','',
        'Motor current-excited GetDP runs use generated slots, teeth, backiron, winding/parallel-path stock and matched passive fin geometry. Onboard fin height and adjoining neck are regenerated together. Operating current/slip/mesh are evaluation context, not physical identity. The 1.3 T linear-material bound and RMS-current limit are fixed; exceeding them cannot be repaired by relabelling the calculation as a pass. Finite height, nonlinear steel, branch current sharing, cooling and moving entry/exit remain gates. Equivalent-volume copper stock is explicitly a takeoff representation, not assembled winding clearance.','',
        '## Coupled decisions and next work','',
        'Every downstream job binds the exact upstream result IDs, payload hashes, candidate and requirement identities, source snapshot and native tool fingerprints. Changed dependencies invalidate its cache. Body/brake material changes feed the same car mass and counted wheel rotational inertia into motor requirements, stopping, station geometry and crowd-sized civil moving-load calculations.','',
        'The selection policy retains Pareto alternatives for declared diagnostic priority, accounted vehicle stock and bare primary stock. Invalid/nonconverged physical values cannot supply objectives. The diagnostic penalty explicitly prioritises unresolved failures; it is not a dollar estimate or a claim of integrated feasibility. Unknown installed equipment, mass distribution and price remain unknown.','',
        f"Next research candidate: **{summary['next_experiment']['selected_candidate_id'] or 'none'}**. Integrated-baseline selection: **{summary['integrated_baseline']['status']}**. Its rejections remain in the comparison record. Native finer motor samples are same-model verification and cannot satisfy independent-domain or physical qualification requirements.",'',
        'Nine same-candidate 1.5/2/3 km load scenarios are prepared for each alternative. Physical journeys stop at an explicit evidence gate because the centred force samples do not supply a valid position-dependent entry/exit map, qualified wheel/brake plant or flexible-body modes. No length/overlap scaling or ideal prescribed acceleration is presented as a physical train journey. Required profiles and station resource bounds are retained separately.','',
        'The brake design can generate larger counted actuator housings and reevaluate the prior native-Chrono checked pure-rolling force law. Supplier friction/fade, real WSP, installation and safety floor remain unknown. Adhesion below downhill grade is a system incompatibility: extra brake torque cannot make that operating envelope safe. Next tasks include route/protection changes rather than repeatedly increasing brake size.','',
        '[Typed next engineering tasks](next-tasks.json) carry candidate/trigger identities, allowed scope and native-job/runtime limits. Reaching a campaign budget completes that bounded run; it does not close the engineering requirement. Further campaigns can expand physical families or improve deficient evaluators without rewriting prior evidence.','',
        '## Generated research twins','',
        'Every candidate receives native FreeCAD/STEP, reopened IFC and matched material takeoff, engineering/manufacturing BOM, assembly/QA/procurement/maintenance drafts. These cover exact known stock in separate car, station and beam frames. Unknown/unlocated equipment is listed without placeholder solids. Complete installed geometry, CG/inertia, costs and assembly qualification remain open. The next-experiment native twin is included below; all candidate native packages are retained locally and indexed.','',
        '[Selected native twin](selected-native-twin.tar.gz) · [All candidate comparison](comparison.json.gz) · [Campaign definition](definition.json) · [Execution journal](journal.json) · [Native input/log index](native-evidence.tar.gz) · [Publication receipt](manifest.json)','',
        'Large raw meshes/fields and alternative native CAD packages remain in ignored build directories with SHA-256 indexes. Remote artifact storage is not configured. Compact retained evidence can be checked; omitted raw bytes require regeneration or access to those local packages.','',
        '```bash','./osr design campaign create campaigns/v06-wheel-lim.toml','./osr design campaign run <campaign-id>','./osr design campaign compare <campaign-id>','./osr design campaign publish <campaign-id>','.venv/bin/python -m engineering.design_search.wheel_publication --verify','```','',
        'The runner reuses exact-context completed work after interruption and refuses changed source/tool epochs. `--max-jobs 1` provides a bounded interruption demonstration; resume with the same ID. Physical/operational qualification and equal-service economics remain independent release gates.','']
    return '\n'.join(lines)


def publish(campaign_id,*,state=campaign.STATE,output=OUTPUT):
    comparison=campaign.compare(campaign_id,state=state);definition=campaign.definition(campaign_id,state=state)
    folder=Path(state)/'campaigns'/campaign_id;out=Path(output)
    if out.exists():
        try:
            if verify(out)['campaign_id']==campaign_id:return verify(out)
        except (ValueError,OSError,KeyError):pass
        previous=ROOT/'build/v06-loop/replaced-publications'/digest(out/'manifest.json');previous.parent.mkdir(parents=True,exist_ok=True)
        if previous.exists():shutil.rmtree(out)
        else:shutil.move(out,previous)
    out.mkdir(parents=True);twins=[];rows=[];selected=comparison['next_experiment']['selected_candidate_id']
    for c in comparison['candidates']:
        results=[r for r in comparison['results']+comparison['confirmations'] if r['candidate_id']==c['candidate_id']]
        raw=ROOT/'build/v06-loop/twins'/campaign_id/c['candidate_id']
        result=wheel_twin.verify(raw) if (raw/'manifest.json').is_file() else wheel_twin.compile(c,results,output=raw,export_native=True,allow_incomplete=True)
        # Full native alternatives stay local; compact draft records travel in Git.
        dest=out/'twins'/c['candidate_id'];dest.mkdir(parents=True)
        for p in raw.iterdir():
            if p.is_file() and p.suffix in ('.json','.md') and p.name not in ('native-result.json','native-input.json','candidate.json','evaluations.json','engineering-bom.json','manifest.json'):shutil.copyfile(p,dest/p.name)
        for n in ('candidate.json','engineering-bom.json','evaluations.json','native-input.json'):(dest/(n+'.gz')).write_bytes(gzip.compress((raw/n).read_bytes(),mtime=0))
        (dest/'native-package-index.json').write_bytes(k.encoded(dict(local_native_directory=str(raw),remote_storage=None,raw_manifest=json.loads((raw/'manifest.json').read_bytes()),**FLAGS)))
        text=(dest/'README.md').read_text()
        if c['candidate_id']==selected:
            text=text.replace('(wheel-stock.FCStd)','(../../selected-native-twin.tar.gz)').replace('(wheel-stock.step)','(../../selected-native-twin.tar.gz)').replace('(wheel-stock.ifc)','(../../selected-native-twin.tar.gz)')
        else:
            text=text.replace('[Native FreeCAD](wheel-stock.FCStd) · [STEP](wheel-stock.step) · [IFC](wheel-stock.ifc)','Native CAD/STEP/IFC for this candidate remain in its indexed local package; no other candidate geometry is substituted.')
        text=text.replace('(engineering-bom.json)','(engineering-bom.json.gz)');(dest/'README.md').write_text(text+'\nFull alternative native package is local and indexed; the linked archive contains only the selected next experiment.\n')
        twins.append(dict(candidate_id=c['candidate_id'],local_native_manifest_id=result['manifest_id'] if 'manifest_id' in result else json.loads((raw/'manifest.json').read_bytes())['manifest_id'],native_directory=str(raw)))
        rows.append(_row(c,results))
    selected=comparison['next_experiment']['selected_candidate_id']
    if selected:(out/'selected-native-twin.tar.gz').write_bytes(archive(ROOT/'build/v06-loop/twins'/campaign_id/selected))
    evidence=ROOT/'build/v06-loop/compact-evidence'/campaign_id;evidence.mkdir(parents=True,exist_ok=True)
    for attempt in sorted((folder/'attempts').glob('*/*')):
        receipt=attempt/'attempt.json'
        if receipt.is_file():
            target=evidence/(attempt.parent.name+'.tar.gz')
            if not target.exists():target.write_bytes(archive(attempt,compact=True))
    (out/'native-evidence.tar.gz').write_bytes(archive(evidence))
    patch=ROOT/'build/v06-loop/material-patch-r2'
    if patch.is_dir():(out/'material-patch.tar.gz').write_bytes(archive(patch))
    preliminary=ROOT/'build/v06-loop/preliminary-campaign.json.gz'
    if preliminary.is_file():(out/'preliminary-resource-failure.json.gz').write_bytes(preliminary.read_bytes())
    journal=json.loads((folder/'journal.json').read_bytes())
    summary=dict(schema='osr-wheel-iterative-campaign-publication/1',campaign_id=campaign_id,generations=len(journal['generations']),
        primary_jobs=len(comparison['results']),confirmation_jobs=len(comparison['confirmations']),
        candidates=rows,twins=twins,next_experiment=comparison['next_experiment'],integrated_baseline=comparison['integrated_baseline'],
        city_performance_packages_written=0,physical_journey_completed=False,**FLAGS)
    for name,value in [('definition.json',definition),('journal.json',journal),('summary.json',summary),('next-tasks.json',[t for r in rows for t in r['next_tasks']])]: (out/name).write_bytes(k.encoded(value))
    (out/'comparison.json.gz').write_bytes(gzip.compress(k.encoded(comparison),mtime=0));(out/'README.md').write_text(readme(summary))
    manifest=dict(schema='osr-wheel-campaign-publication-manifest/1',campaign_id=campaign_id,source_sha256=definition['source_sha256'],
        files_sha256={p.relative_to(out).as_posix():digest(p) for p in sorted(out.rglob('*')) if p.is_file()},**FLAGS)
    manifest['manifest_id']=k.identity(manifest);(out/'manifest.json').write_bytes(k.encoded(manifest));return verify(out)


def verify(output=OUTPUT):
    out=Path(output);m=json.loads((out/'manifest.json').read_bytes());summary=json.loads((out/'summary.json').read_bytes())
    if m['manifest_id']!=k.identity({key:value for key,value in m.items() if key!='manifest_id'}):raise ValueError('Campaign publication identity differs')
    if {p.relative_to(out).as_posix():digest(p) for p in out.rglob('*') if p.is_file() and p.relative_to(out).as_posix()!='manifest.json'}!=m['files_sha256']:raise ValueError('Campaign publication payload differs')
    for name,h in m['source_sha256'].items():
        if digest(ROOT/name)!=h:raise ValueError('Campaign publication source differs: '+name)
    comp=json.loads(gzip.decompress((out/'comparison.json.gz').read_bytes()));definition=json.loads((out/'definition.json').read_bytes())
    if k.identity({key:value for key,value in comp.items() if key!='comparison_sha256'})!=comp['comparison_sha256']:raise ValueError('Campaign comparison differs')
    for c in comp['candidates']:wheel_families.validate_supported(c)
    for r in comp['results']+comp['confirmations']:k.validate_result(r)
    expected=selection.select(comp['candidates'],comp['results'],purpose='next-experiment',policy=definition['specification']['policy'])
    if expected!=summary['next_experiment'] or expected!=comp['next_experiment']:raise ValueError('Replayed Pareto selection differs')
    policy=campaign._baseline_policy(definition['specification'],comp['results'],comp['confirmations'])
    if selection.select(comp['candidates'],comp['results']+comp['confirmations'],purpose='integrated-baseline',policy=policy)!=summary['integrated_baseline']:raise ValueError('Integrated hold differs')
    if any(record.get(key) is not value for record in (summary,m) for key,value in FLAGS.items()):raise ValueError('Campaign cannot release a railway')
    return dict(verified=True,campaign_id=m['campaign_id'],physical_candidates=len(comp['candidates']),generations=summary['generations'],
        next_experiment_id=expected['selected_candidate_id'],integrated_baseline=summary['integrated_baseline']['status'],**FLAGS)


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--verify',action='store_true');p.add_argument('--publish');a=p.parse_args()
    print(json.dumps(publish(a.publish) if a.publish else verify(),indent=2))
